mapper.select:
SELECT PERSON_NAME FROM (
	SELECT PERSON_NAME
	FROM PERSON_NAME
	WHERE COUNTRY_CODE = #{birthCountry}
	  AND GENDER = #{gender}
	ORDER BY DBMS_RANDOM.VALUE
)
WHERE ROWNUM = 1

SELECT PERSON_NAME
FROM PERSON_NAME
WHERE COUNTRY_CODE = #{countryCode}
  AND GENDER = #{gender}
ORDER BY PERSON_NAME

SELECT HIST_NAME
FROM COUNTRY_NAME_HIST
WHERE COUNTRY_CODE = #{birthCountry}
  AND START_YEAR <= #{birthYear}
  AND (END_YEAR IS NULL OR END_YEAR >= #{birthYear})
  AND ROWNUM = 1

SELECT LIFE_ID AS lifeId, MEMBER_ID AS memberId, GUEST_TOKEN AS guestToken, START_TYPE AS startType, NAME AS name, GENDER AS gender, BIRTH_COUNTRY AS birthCountry, CURRENT_COUNTRY AS currentCountry, BIRTH_YEAR AS birthYear, WEALTH_CLASS AS wealthClass, IS_URBAN AS isUrban, CURRENT_AGE AS currentAge, HEALTH AS health, HAPPINESS AS happiness, KNOWLEDGE AS knowledge, RELATION AS relation, IS_MARRIED AS marriedYn, CHILD_COUNT AS childCount, PARENT_ALIVE AS parentAlive, EDU_LEVEL AS eduLevel, SCHOOL_STATUS AS schoolStatus, DROP_REASON AS dropReason, JOB_ID AS jobId, JOB_STATUS AS jobStatus, JOB_YEARS AS jobYears, PREP_SCORE AS prepScore, INCOME_RATE AS incomeRate, NVL(INCOME, 0) AS income, NVL(ASSETS, 0) AS assets, PENSION AS pension, STAGE_CODE AS stageCode, FOCUS_CODE AS focusCode, PENDING_EVENT_ID AS pendingEventId, INVEST_TYPE AS investType, OWNS AS owns, NVL(ORIGIN_CLASS, WEALTH_CLASS) AS originClass, HOUSE_VALUE AS houseValue, STATUS AS status FROM LIFE WHERE STATUS = 'PLAYING'
AND MEMBER_ID = #{memberId}
AND GUEST_TOKEN = #{guestToken} AND MEMBER_ID IS NULL

mapper.insert:
INSERT INTO LIFE_YEAR_LOG (
	LIFE_ID, AGE, YEAR_NO, COUNTRY_CODE,
	HEALTH, HAPPINESS, KNOWLEDGE, RELATION, FOCUS_CODE, EDU_LEVEL,
	JOB_ID, INCOME, ASSETS
) VALUES (
	#{lifeId}, #{currentAge}, #{birthYear} + #{currentAge}, #{currentCountry},
	ROUND(#{health}), ROUND(#{happiness}), ROUND(#{knowledge}), ROUND(#{relation}),
	#{focusCode, jdbcType=VARCHAR}, #{eduLevel, jdbcType=VARCHAR},
	CASE WHEN #{jobStatus, jdbcType=VARCHAR} = 'EMPLOYED' THEN #{jobId, jdbcType=VARCHAR} END, #{income}, #{assets}
)

mapper.select:
SELECT LOG_TEXT FROM (
	SELECT LOG_TEXT FROM LIFE_EVENT_LOG
	WHERE LIFE_ID = #{lifeId}
	  AND EVENT_ID = #{pendingEventId}
	  AND CHOICE_ID IS NULL
	ORDER BY LOG_ID DESC
) WHERE ROWNUM = 1

SELECT COUNT(*) FROM LIFE_EVENT_LOG
WHERE LIFE_ID = #{lifeId}
  AND EVENT_ID = #{pendingEventId}
  AND CHOICE_ID IS NOT NULL
  AND AGE = #{currentAge} - 1

SELECT d.CAUSE_NAME AS causeName,
       d.RATIO      AS ratio
FROM REGION_DEATH_CAUSE d
JOIN COUNTRY c ON d.REGION_CODE = c.REGION_CODE
WHERE c.COUNTRY_CODE = #{countryCode}
  AND d.AGE_GROUP = #{ageGroup}
  AND d.DECADE = (
	SELECT DECADE FROM (
		SELECT d2.DECADE
		FROM REGION_DEATH_CAUSE d2
		JOIN COUNTRY c2 ON d2.REGION_CODE = c2.REGION_CODE
		WHERE c2.COUNTRY_CODE = #{countryCode}
		  AND d2.AGE_GROUP = #{ageGroup}
		ORDER BY ABS(d2.DECADE - TRUNC(#{yearNo} / 10) * 10)
	)
	WHERE ROWNUM = 1
  )

mapper.delete:
BEGIN
	DELETE FROM LIFE_COSTUME     WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE_QUEST       WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE_TRAIT       WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE_EXPERIENCE  WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE_EVENT_LOG   WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE_YEAR_LOG    WHERE LIFE_ID = #{lifeId};
	DELETE FROM QA_LOG           WHERE LIFE_ID = #{lifeId};
	DELETE FROM AI_STORY         WHERE LIFE_ID = #{lifeId};
	UPDATE POINT_HISTORY SET LIFE_ID = NULL WHERE LIFE_ID = #{lifeId};
	DELETE FROM LIFE             WHERE LIFE_ID = #{lifeId};
END;
